<style>
*{box-sizing:border-box}body{margin:0;background:#030605;color:#effff7;font-family:Inter,system-ui,sans-serif}body:before{content:"";position:fixed;inset:0;background:radial-gradient(circle at 50% 0,#145437,transparent 42%),radial-gradient(circle at 10% 90%,#0b3021,transparent 30%);pointer-events:none}.wrap{width:min(1100px,92%);margin:auto;position:relative}.top{padding:25px 0;display:flex;justify-content:space-between}.brand{font-weight:950;letter-spacing:.08em}.brand b{color:#5cffaa}.badge,.chip{border:1px solid #5cffaa25;background:#5cffaa0c;color:#8fffc3;border-radius:999px;padding:8px 12px;font-size:12px}.hero{text-align:center;padding:65px 0 35px}.orb{width:100px;height:100px;margin:auto auto 28px;border-radius:50%;background:radial-gradient(circle at 32% 28%,#e7fff2,#5cffaa 25%,#087d4c 58%,#021b10 75%);box-shadow:0 0 45px #5cffaa66,0 0 120px #5cffaa22;animation:f 4s ease-in-out infinite}.hero h1{font-size:clamp(42px,8vw,82px);line-height:.92;letter-spacing:-.06em;margin:0}.hero h1 span{color:#5cffaa}.hero p{max-width:720px;margin:22px auto 35px;color:#91a99d;font-size:17px;line-height:1.65}.search{max-width:820px;margin:auto;display:flex;gap:8px;padding:9px;border:1px solid #5cffaa28;border-radius:20px;background:#0c1712cc;backdrop-filter:blur(20px)}input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:white;padding:16px;font-size:16px}button{border:0;border-radius:14px;background:#5cffaa;color:#03130b;font-weight:900;padding:0 25px;cursor:pointer}.result{display:none;text-align:left;margin:25px auto 60px;max-width:900px}.result.show{display:block}.card{background:#0b1511e8;border:1px solid #ffffff12;border-radius:20px;padding:20px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.kv{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid #ffffff09}.kv b{color:#9dffca}.ok{color:#5cffaa}.warn{color:#ffd37a}.bad{color:#ff808b}.notice{position:fixed;right:18px;bottom:18px;width:min(410px,calc(100% - 36px));z-index:9;background:#09130ff5;border:1px solid #5cffaa35;border-radius:20px;padding:18px;box-shadow:0 20px 70px #000b}.notice img{width:100%;max-height:210px;object-fit:cover;border-radius:14px;margin-bottom:12px}.notice audio{width:100%;margin-top:12px}.poll label{display:block;margin:8px 0;padding:10px;border:1px solid #ffffff12;border-radius:12px}.poll button{height:42px;margin-top:10px}.reportlink{color:#8fffc3}.loading{display:none;text-align:center;color:#91a99d;margin:25px}.loading.show{display:block}@keyframes f{50%{transform:translateY(-9px)}}@media(max-width:650px){.search{flex-direction:column}.search button{height:52px}.grid{grid-template-columns:1fr}.badge{display:none}}
